import os
import boto3

def extract_text(payload, config=None):
    config = config or {}
    client = boto3.client('textract', region_name='us-west-2')
    response = client.analyze_document(
        Document={'Bytes': payload},
        FeatureTypes=['TABLES', 'FORMS'] if 'layout' in config else ['TEXT']
    )
    result = {
        'text':''.join([item['Text'] for item in response['Blocks'] if item['BlockType'] == 'LINE']),
        'layout': response['Blocks'] if 'layout' in config else None
    }
    return result
